import subprocess


def _run_calendar_sync(email: str, count: int) -> None:
    # Refresh the scheduling calendar cache so freed slots become bookable again
    try:
        subprocess.run(
            ['python', 'scripts/sync_calendar_slots.py', '--email', email, '--released', str(count)],
            check=True,
            timeout=60,
        )
    except Exception as e:
        app.logger.error(f'Calendar sync job failed for {email}: {e}')


@tool
def cancel_appointment(email: str) -> str:
    if not is_valid_email(email):
        return 'Invalid email address. Please provide a valid email.'
    appointments = get_appointments_by_email(email)
    if not appointments:
        return 'No appointments found for this email. Nothing to cancel.'
    success, count = delete_appointments_by_email(email)
    if not success:
        return 'Failed to cancel appointments. Please try again.'
    _run_calendar_sync(email, count)
    try:
        subject = 'Your Appointment Cancellation'
        body = make_cancellation_message(email, count)
        send_email(to_address=email, subject=subject, body=body)
    except Exception as e:
        app.logger.error(f'Email send error for {email}: {e}')
    return f'❌ Successfully cancelled {count} appointment{('s' if count > 1 else '')} for **{email}**. A cancellation confirmation email has been sent.'
